  // Logika spec var representing port state for outgoing data port
  @spec var recovery_frame: EIT_Acquisition_Supervisor.RecoveryFrame = $

  def put_recovery_frame(value : EIT_Acquisition_Supervisor.RecoveryFrame) : Unit = {
    Contract(
      Modifies(recovery_frame),
      Ensures(
        recovery_frame == value
      )
    )
    Spec {
      recovery_frame = value
    }

    Art.putValue(recovery_frame_Id, EIT_Acquisition_Supervisor.RecoveryFrame_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

